class TypeChecker
{
    /** @phpstan-assert-if-true array<string, mixed>|NULL $value */
    public static function isArrayStringMixedNull(mixed $value): bool
    {
        if ($value === NULL) {
            return TRUE;
        }
        if (!is_array($value)) {
            return FALSE;
        }
        foreach ($value as $key => $item) {
            if (!is_string($key)) {
                return FALSE;
            }
        }
        return TRUE;
    }
}

